+void BuildTextIndexTransform::flushPendingBlocks()
+{
+    if (pending_blocks.empty())
+        return;
+
+    chassert(build_pool.has_value());
+    ThreadPoolCallbackRunnerLocal<void> runner(*build_pool, ThreadName::MERGETREE_TEXT_INDEX);
+
+    for (size_t s = 0; s < slots.size(); ++s)
+    {
+        /// TOKEN partitioning: every slot walks EVERY buffered block in row order, but its builders
+        /// keep only the tokens whose hash selects that slot (MergeTreeIndexTextGranuleBuilder::
+        /// addToken). Vocabularies are therefore disjoint, so a ~40k dictionary is built once across
+        /// the slots instead of once per slot, and the segments stay cheap to combine. The row numbers
+        /// each slot sees still only increase, which is the order PostingListBuilder::add requires.
+        /// Each slot owns its builders, arena and posting lists, so nothing mutable is shared.
+        runner.enqueueAndKeepTrack([this, s]
+        {
+            auto & slot = slots[s];
+
+            for (const auto & pending : pending_blocks)
+            for (size_t i = 0; i < indexes.size(); ++i)
+            {
+                size_t pos = 0;
+                auto & aggregator_text = typeid_cast<MergeTreeIndexAggregatorText &>(*slot.aggregators[i]);
+                aggregator_text.setTokenShard(s, build_threads);
+                aggregator_text.setCurrentRow(pending.start_row);
+
+                const auto memory_usage_before_update = getCurrentThreadMemoryUsage();
+                aggregator_text.update(pending.block, &pos, pending.block.rows());
+                const auto memory_usage_after_update = getCurrentThreadMemoryUsage();
+
+                if (memory_usage_after_update > memory_usage_before_update)
+                    slot.estimated_allocated_bytes[i]
+                        += static_cast<size_t>(memory_usage_after_update - memory_usage_before_update);
+            }
+        });
+    }
+
+    runner.waitForAllToFinishAndRethrowFirstError();
+    pending_blocks.clear();
+
+    /// Writing files and deciding flushes stays on this thread.
+    for (size_t s = 0; s < slots.size(); ++s)
