#### A table read through a view with `final=1` under a `currentUser()` row policy

A table uses ReplacingMergeTree and is read through a view with final=1. It has a row policy whose filter calls currentUser(). In 26.10, that policy is no longer applied as PREWHERE before FINAL. FINAL therefore merges every row, including a large String column, before the policy filters them. Results are identical.

```sql
CREATE TABLE default.t1 (`c1` String, `c2` String, `c4` String, `c5` DateTime, `c6` String, `c7` UInt8) ENGINE = ReplacingMergeTree(c5, c7) PARTITION BY c4 ORDER BY (c1, c2, c4);
INSERT INTO default.t1 SELECT toString(cityHash64(number)), if(number % 500 = 0, 'def', toString(number % 997)), ['a','b','c','d'][number % 4 + 1], toDateTime('2026-01-01 00:00:00') + number, concat('{"p":{"r":"', if(number % 7 = 0, '00000000-aaaa-4bbb-8ccc-000000000001', 'none'), '","t":"', repeat('z', 600), '"}}'), 0 FROM numbers(1500000);
INSERT INTO default.t1 SELECT toString(cityHash64(number)), if(number % 500 = 0, 'def', toString(number % 997)), ['a','b','c','d'][number % 4 + 1], toDateTime('2026-03-01 00:00:00') + number, concat('{"p":{"r":"', if(number % 3 = 0, '00000000-AAAA-4bbb-8ccc-000000000001', 'none'), '","t":"', repeat('z', 600), '"}}'), 0 FROM numbers(750000, 1500000);
CREATE VIEW default.v1 AS SELECT * FROM default.t1 SETTINGS final = 1;
CREATE ROW POLICY p1 ON default.t1 USING c2 = substring(currentUser(), 1, 3) TO default;
SELECT c4, count() AS n FROM default.v1 WHERE c6 ILIKE '%00000000-aaaa-4bbb-8ccc-000000000001%' GROUP BY c4 ORDER BY n DESC LIMIT 10
SETTINGS compatibility = '24.0';
```

